package com.killsto;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(KillsToConfig.GROUP)
public interface KillsToConfig extends Config
{
    String GROUP = "killsto";
    String RUNEPROFILE_WARNING = "This plugin may send your RuneScape character name and the current activity's " +
        "Collection Log page to api.runeprofile.com, a third-party server not controlled or verified by the " +
        "RuneLite developers. The service also receives your IP address as part of the connection.";

    @ConfigSection(
        name = "Developer tools",
        description = "Testing controls for cached Collection Log data",
        position = 99,
        closedByDefault = true
    )
    String developerTools = "developerTools";

    @ConfigItem(
        keyName = "showOverlay",
        name = "Show overlay",
        description = "Show the temporary viewport overlay. Sidebar tracking remains active."
    )
    default boolean showOverlay()
    {
        return true;
    }

    @Range(min = 15, max = 600)
    @ConfigItem(
        keyName = "visibilitySeconds",
        name = "Overlay duration (secs)",
        description = "Seconds to retain the overlay after an encounter ends"
    )
    default int visibilitySeconds()
    {
        return 120;
    }

    @Range(min = 1, max = 6)
    @ConfigItem(
        keyName = "maxOverlayItems",
        name = "Items on overlay (1-6)",
        description = "Maximum missing Collection Log items shown in the viewport overlay"
    )
    default int maxOverlayItems()
    {
        return 3;
    }

    @ConfigItem(keyName = "showItemIcons", name = "Show item icons", description = "Show item icons")
    default boolean showItemIcons()
    {
        return true;
    }

    @ConfigItem(keyName = "showItemNames", name = "Show item names", description = "Show item names")
    default boolean showItemNames()
    {
        return true;
    }

    @ConfigItem(keyName = "showWikiRates", name = "Show Wiki rates", description = "Show bundled Wiki drop rates")
    default boolean showWikiRates()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showVariableRateMetrics",
        name = "Show variable-rate text",
        description = "Show rate varies and chance varies for contribution-dependent drops"
    )
    default boolean showVariableRateMetrics()
    {
        return true;
    }

    @ConfigItem(keyName = "metricMode", name = "Metric", description = "Choose the dry-progress metric")
    default MetricMode metricMode()
    {
        return MetricMode.BOTH;
    }

    @ConfigItem(
        keyName = "showDryJokes",
        name = "Show dry jokes",
        description = "Show a short joke when any missing item passes a usable drop-rate threshold"
    )
    default boolean showDryJokes()
    {
        return true;
    }

    @ConfigItem(
        keyName = "enableRuneProfileFallback",
        name = "RuneProfile fallback",
        description = "Send your RSN to api.runeprofile.com only when local Collection Log data is missing or stale",
        warning = RUNEPROFILE_WARNING
    )
    default boolean enableRuneProfileFallback()
    {
        return false;
    }

    @Range(min = 1, max = 90)
    @ConfigItem(
        keyName = "staleSyncDays",
        name = "Stale after (days)",
        description = "Days before local Collection Log data is stale"
    )
    default int staleSyncDays()
    {
        return 14;
    }

    @ConfigItem(keyName = "autoOpenOnInstall", name = "Open on install", description = "Open the Kills To sidebar once after installation")
    default boolean autoOpenOnInstall()
    {
        return true;
    }

    @ConfigItem(keyName = "autoOpenOnUpdates", name = "Open on updates", description = "Open release notes once after each update")
    default boolean autoOpenOnUpdates()
    {
        return true;
    }

    @ConfigItem(
        keyName = "clearActiveCollectionCache",
        name = "Clear active CLog cache",
        description = "Toggle either way to clear local and RuneProfile ownership data for the currently displayed activity",
        warning = "This makes the active activity unsynced until local capture or RuneProfile fallback restores it.",
        section = developerTools,
        position = 0
    )
    default boolean clearActiveCollectionCache()
    {
        return false;
    }
}

package com.killsto;

import com.killsto.model.ActivityDisplayModel;
import com.killsto.model.DropProgress;
import com.killsto.model.SyncState;
import com.killsto.service.KillsToService;
import com.killsto.ui.DropRowComponent;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.text.DecimalFormat;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.AsyncBufferedImage;

public final class KillsToOverlay extends OverlayPanel
{
    private static final DecimalFormat PERCENT = new DecimalFormat("0.0%");
    private final KillsToConfig config;
    private final ItemManager itemManager;
    private KillsToService service;

    @Inject
    public KillsToOverlay(KillsToConfig config, ItemManager itemManager)
    {
        this.config = config;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(225, 0));
    }

    void setService(KillsToService service)
    {
        this.service = service;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (service == null || !service.isOverlayVisible(Instant.now()))
        {
            return null;
        }
        ActivityDisplayModel model = service.getModel();
        if (model == null)
        {
            return null;
        }
        panelComponent.getChildren().add(TitleComponent.builder()
            .text(model.getActivity().getName() + " · " + model.getKillCountText())
            .build());
        if (model.getActivity().getDisplayUnit() != model.getActivity().getRateUnit())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Dry counter")
                .right(model.getRateCountText())
                .build());
        }
        if (model.getSyncState() == SyncState.NOT_SYNCED)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Sync Collection Log in sidebar")
                .build());
            return super.render(graphics);
        }
        if (model.getMissing().isEmpty())
        {
            panelComponent.getChildren().add(LineComponent.builder().left("Collection complete").build());
            return super.render(graphics);
        }
        int visibleItems = Math.min(config.maxOverlayItems(), model.getMissing().size());
        for (DropProgress progress : model.getMissing().subList(0, visibleItems))
        {
            addDropRow(progress);
        }
        int remainingItems = model.getMissing().size() - visibleItems;
        if (remainingItems > 0)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("+" + remainingItems + " more missing")
                .build());
        }
        if (config.showDryJokes() && model.getDryMessage() != null)
        {
            panelComponent.getChildren().add(LineComponent.builder().left(model.getDryMessage()).build());
        }
        return super.render(graphics);
    }

    private void addDropRow(DropProgress progress)
    {
        boolean hideVariableMetrics = progress.getDrop().isVariableRate() &&
            !config.showVariableRateMetrics();
        List<String> details = createDropDetails(progress, hideVariableMetrics);
        AsyncBufferedImage image = config.showItemIcons()
            ? itemManager.getImage(progress.getDrop().getItemId())
            : null;
        if (image != null || !details.isEmpty())
        {
            panelComponent.getChildren().add(new DropRowComponent(image, details));
        }
    }

    private List<String> createDropDetails(DropProgress progress, boolean hideVariableMetrics)
    {
        List<String> details = new ArrayList<>();
        if (config.showItemNames())
        {
            details.add(progress.getDrop().getName());
        }
        if (config.showWikiRates())
        {
            details.add(progress.getDrop().rateText());
        }
        if (hideVariableMetrics)
        {
            return details;
        }

        ActivityDisplayModel model = service.getModel();
        String rateMetric = progress.progressMetric(model.getActivity().getRateUnit());
        if (config.metricMode() == MetricMode.KILLS_TO || config.metricMode() == MetricMode.BOTH)
        {
            details.add(rateMetric);
        }
        if (config.metricMode() == MetricMode.CUMULATIVE_CHANCE || config.metricMode() == MetricMode.BOTH)
        {
            details.add(chanceText(progress));
        }
        return details;
    }

    private String chanceText(DropProgress progress)
    {
        if (!progress.hasExactRate())
        {
            return "chance varies";
        }
        return progress.isCountKnown() ? PERCENT.format(progress.getCumulativeChance()) : "chance ?";
    }
}

package com.killsto;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.killsto.data.ActivityCatalog;
import com.killsto.model.ActivityDefinition;
import com.killsto.model.ActivityDisplayModel;
import com.killsto.model.ActivityDrop;
import com.killsto.model.OwnershipSource;
import com.killsto.model.SyncState;
import com.killsto.service.CollectionLogCounterParser;
import com.killsto.service.KillCountParser;
import com.killsto.service.KillsToService;
import com.killsto.service.RuneProfileClient;
import com.killsto.ui.KillsToPanel;
import java.awt.image.BufferedImage;
import java.text.NumberFormat;
import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.OptionalInt;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.ScriptID;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
    name = "Kills To",
    description = "Shows missing Collection Log drops, rates, and dry progress for supported activities",
    tags = {"boss", "minigame", "collection", "log", "clog", "kc", "drops"}
)
public class KillsToPlugin extends Plugin
{
    static final String VERSION = "0.4.4";
    private static final String ACKNOWLEDGED_VERSION = "acknowledgedVersion";
    private static final String RUNEPROFILE_CONSENT = "runeProfileConsent";
    private static final Duration RUNEPROFILE_RETRY_DELAY = Duration.ofMinutes(5);

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar clientToolbar;
    @Inject private OverlayManager overlayManager;
    @Inject private ConfigManager configManager;
    @Inject private KillsToConfig config;
    @Inject private Gson gson;
    @Inject private KillsToOverlay overlay;
    @Inject private ItemManager itemManager;
    @Inject private RuneProfileClient runeProfileClient;

    private final KillCountParser killCountParser = new KillCountParser();
    private final CollectionLogCounterParser collectionLogCounterParser = new CollectionLogCounterParser();
    private ActivityCatalog catalog;
    private KillsToService service;
    private KillsToPanel panel;
    private NavigationButton navigationButton;
    private ActivityDefinition regionActivity;
    private boolean rewardGuardianCheckVisible;
    private String lastCollectionSyncSignature;
    private final Map<String, Instant> runeProfileAttempts = new HashMap<>();
    private final Set<String> runeProfileInFlight = new HashSet<>();

    @Provides
    KillsToConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(KillsToConfig.class);
    }

    @Override
    protected void startUp()
    {
        prepareRuneProfileConsent();
        catalog = ActivityCatalog.load(gson);
        service = new KillsToService(config, configManager);
        panel = new KillsToPanel(config, itemManager, this::requestCollectionLogSync);
        service.addListener(panel::updateModel);
        service.addListener(this::requestRuneProfileFallback);
        overlay.setService(service);
        overlayManager.add(overlay);

        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/killsto/icon.png");
        navigationButton = NavigationButton.builder()
            .tooltip("Kills To")
            .icon(icon)
            .priority(7)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navigationButton);
        requestRuneProfileConsent();
        openForInstallOrUpdate();
    }

    private void prepareRuneProfileConsent()
    {
        if (configManager.getConfiguration(KillsToConfig.GROUP, RUNEPROFILE_CONSENT) == null)
        {
            configManager.setConfiguration(
                KillsToConfig.GROUP,
                "enableRuneProfileFallback",
                false);
        }
    }

    private void requestRuneProfileConsent()
    {
        if (configManager.getConfiguration(KillsToConfig.GROUP, RUNEPROFILE_CONSENT) != null)
        {
            return;
        }

        SwingUtilities.invokeLater(() ->
        {
            Object[] options = {"Enable RuneProfile", "Keep off"};
            int result = JOptionPane.showOptionDialog(
                null,
                KillsToConfig.RUNEPROFILE_WARNING +
                    "\n\nEnable RuneProfile fallback? Local Collection Log data remains authoritative.",
                "Kills To: RuneProfile fallback",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE,
                null,
                options,
                options[0]);
            boolean enabled = result == JOptionPane.YES_OPTION;
            configManager.setConfiguration(
                KillsToConfig.GROUP,
                RUNEPROFILE_CONSENT,
                enabled ? "accepted" : "declined");
            configManager.setConfiguration(
                KillsToConfig.GROUP,
                "enableRuneProfileFallback",
                enabled);
        });
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
        }
        if (service != null)
        {
            service.clear();
        }
        navigationButton = null;
        panel = null;
        service = null;
        catalog = null;
        rewardGuardianCheckVisible = false;
        lastCollectionSyncSignature = null;
        runeProfileAttempts.clear();
        runeProfileInFlight.clear();
    }

    @Subscribe
    public void onInteractingChanged(InteractingChanged event)
    {
        if (service == null || catalog == null)
        {
            return;
        }
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null || event.getSource() != localPlayer)
        {
            return;
        }
        Actor target = event.getTarget();
        if (target instanceof NPC)
        {
            ActivityDefinition activity = catalog.findByNpcId(((NPC) target).getId());
            if (activity != null)
            {
                service.activate(activity, true, Instant.now());
            }
        }
        else if (target == null)
        {
            service.setEncounterActive(false, Instant.now());
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (service == null || catalog == null ||
            (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM))
        {
            return;
        }
        killCountParser.parse(event.getMessage()).ifPresent(result ->
        {
            ActivityDefinition activity = catalog.findByKillCountName(result.getActivityName());
            if (activity != null)
            {
                service.updateKillCount(activity, result.getKillCount(), Instant.now());
            }
        });
        activateForRewardClaim(event.getMessage());
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (service == null || catalog == null || client.getLocalPlayer() == null)
        {
            return;
        }
        captureRewardGuardianCheck();
        int regionId = getStableRegionId();
        ActivityDefinition detected = findLoadedNpcActivity();
        if (detected == null)
        {
            detected = catalog.findByRegionId(regionId);
        }
        if (detected == null && isGuardiansOfTheRiftActive())
        {
            detected = catalog.findByKillCountName("Guardians of the Rift");
        }
        if (detected == null && isZalcanoFightActive())
        {
            detected = catalog.findByKillCountName("Zalcano");
        }
        if (detected != null)
        {
            if (regionActivity == null || !regionActivity.getKey().equals(detected.getKey()))
            {
                regionActivity = detected;
                service.activate(detected, true, Instant.now());
            }
            else
            {
                service.setEncounterActive(true, Instant.now());
            }
        }
        else if (regionActivity != null)
        {
            regionActivity = null;
            service.setEncounterActive(false, Instant.now());
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (service != null && event.getGameState() == GameState.LOGIN_SCREEN)
        {
            regionActivity = null;
            rewardGuardianCheckVisible = false;
            lastCollectionSyncSignature = null;
            runeProfileAttempts.clear();
            runeProfileInFlight.clear();
            service.clear();
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (service == null || !KillsToConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }
        if ("clearActiveCollectionCache".equals(event.getKey()))
        {
            clearActiveCollectionLogCaches();
            return;
        }
        if (panel != null)
        {
            panel.setRuneProfileStatus(config.enableRuneProfileFallback() ? "enabled" : "off");
        }
        if ("enableRuneProfileFallback".equals(event.getKey()) && config.enableRuneProfileFallback())
        {
            runeProfileAttempts.clear();
        }
        service.refresh(Instant.now());
    }

    private void clearActiveCollectionLogCaches()
    {
        ActivityDisplayModel current = service.getModel();
        if (current == null)
        {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "Kills To: no active or recently displayed activity cache to clear.", null);
            return;
        }

        runeProfileAttempts.remove(current.getActivity().getKey());
        ActivityDefinition cleared = service.clearActiveCollectionLogCaches(Instant.now());
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
            "Kills To: cleared local and RuneProfile Collection Log cache for " + cleared.getName() +
                ". " + (config.enableRuneProfileFallback()
                    ? "A fresh RuneProfile fallback request has started."
                    : "Open its Collection Log page to restore local data."), null);
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        if (service == null || catalog == null || event.getScriptId() != ScriptID.COLLECTION_DRAW_LIST)
        {
            return;
        }

        clientThread.invokeLater(this::captureCollectionLogPage);
    }

    private boolean captureCollectionLogPage()
    {
        Widget pageHeader = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
        if (pageHeader == null || pageHeader.getDynamicChildren() == null)
        {
            return false;
        }

        captureCollectionLogCounters(pageHeader);
        Widget title = pageHeader.getChild(0);
        ActivityDefinition activity = title == null ? null : catalog.findByKillCountName(title.getText());
        Widget itemContainer = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
        if (activity == null || itemContainer == null || itemContainer.getChildren() == null)
        {
            return false;
        }

        Set<Integer> catalogItemIds = new HashSet<>();
        for (ActivityDrop drop : activity.getDrops())
        {
            catalogItemIds.add(drop.getItemId());
        }
        Set<Integer> obtainedItemIds = new HashSet<>();
        for (Widget child : itemContainer.getChildren())
        {
            if (child.getOpacity() == 0 && catalogItemIds.contains(child.getItemId()))
            {
                obtainedItemIds.add(child.getItemId());
            }
        }

        Instant now = Instant.now();
        service.syncCollectionLog(activity, obtainedItemIds, now);
        String signature = activity.getKey() + ':' + obtainedItemIds.size() + ':' + obtainedItemIds.hashCode();
        if (!signature.equals(lastCollectionSyncSignature))
        {
            lastCollectionSyncSignature = signature;
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "Kills To: " + activity.getName() + " Collection Log synced locally (" +
                    obtainedItemIds.size() + " tracked items obtained).", null);
        }
        return true;
    }

    private void captureCollectionLogCounters(Widget pageHeader)
    {
        for (Widget child : pageHeader.getDynamicChildren())
        {
            collectionLogCounterParser.parseRiftsSearches(child.getText()).ifPresent(searches ->
            {
                ActivityDefinition guardians = catalog.findByKillCountName("Guardians of the Rift");
                if (guardians != null)
                {
                    service.cacheRateCount(guardians, searches, Instant.now());
                }
            });
            collectionLogCounterParser.parseRewardPermitsClaimed(child.getText()).ifPresent(permits ->
            {
                ActivityDefinition tempoross = catalog.findByKillCountName("Tempoross");
                if (tempoross != null)
                {
                    service.cacheRateCount(tempoross, permits, Instant.now());
                }
            });
            collectionLogCounterParser.parseRewardsClaimed(child.getText()).ifPresent(rewards ->
            {
                ActivityDefinition wintertodt = catalog.findByKillCountName("Wintertodt");
                if (wintertodt != null)
                {
                    service.cacheRateCount(wintertodt, rewards, Instant.now());
                }
            });
        }
    }

    private void requestCollectionLogSync()
    {
        clientThread.invoke(() ->
        {
            if (!captureCollectionLogPage())
            {
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                    "Kills To: open a supported Collection Log boss or minigame page, then click Sync open page.",
                    null);
            }
        });
    }

    private void requestRuneProfileFallback(ActivityDisplayModel model)
    {
        if (panel == null || service == null)
        {
            return;
        }
        if (!config.enableRuneProfileFallback())
        {
            panel.setRuneProfileStatus("off");
            return;
        }
        if (model == null)
        {
            panel.setRuneProfileStatus("enabled");
            return;
        }
        if (model.getSyncState() == SyncState.SYNCED)
        {
            String readyStatus = model.getOwnershipSource() == OwnershipSource.RUNEPROFILE
                ? "enabled · cached" : "enabled · local first";
            panel.setRuneProfileStatus(readyStatus);
            return;
        }

        ActivityDefinition activity = model.getActivity();
        String activityKey = activity.getKey();
        Instant now = Instant.now();
        Instant lastAttempt = runeProfileAttempts.get(activityKey);
        if (runeProfileInFlight.contains(activityKey) ||
            (lastAttempt != null && now.isBefore(lastAttempt.plus(RUNEPROFILE_RETRY_DELAY))))
        {
            return;
        }
        Player localPlayer = client.getLocalPlayer();
        String username = localPlayer == null ? null : localPlayer.getName();
        if (username == null || username.trim().isEmpty())
        {
            panel.setRuneProfileStatus("waiting for login");
            return;
        }

        runeProfileAttempts.put(activityKey, now);
        runeProfileInFlight.add(activityKey);
        panel.setRuneProfileStatus("loading " + activity.getName());
        runeProfileClient.fetchCollectionLogPage(username, activity, result ->
            clientThread.invokeLater(() -> applyRuneProfileResult(username, activity, result)));
    }

    private void applyRuneProfileResult(
        String username,
        ActivityDefinition activity,
        RuneProfileClient.Result result)
    {
        runeProfileInFlight.remove(activity.getKey());
        Player localPlayer = client.getLocalPlayer();
        if (service == null || panel == null || !config.enableRuneProfileFallback() ||
            localPlayer == null || !username.equalsIgnoreCase(localPlayer.getName()))
        {
            return;
        }

        if (result.getStatus() == RuneProfileClient.Status.SUCCESS)
        {
            service.syncRuneProfileCollectionLog(activity, result.getObtainedItemIds(), Instant.now());
            panel.setRuneProfileStatus("synced " + activity.getName());
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "Kills To: " + activity.getName() + " Collection Log loaded from RuneProfile (" +
                    result.getObtainedItemIds().size() + " tracked items obtained).", null);
        }
        else if (result.getStatus() == RuneProfileClient.Status.NOT_FOUND)
        {
            panel.setRuneProfileStatus("profile not found");
        }
        else if (result.getStatus() == RuneProfileClient.Status.RATE_LIMITED)
        {
            panel.setRuneProfileStatus("rate limited · retry later");
        }
        else
        {
            panel.setRuneProfileStatus("unavailable · retry later");
        }
    }

    private void captureRewardGuardianCheck()
    {
        int[] dialogueTextWidgets = {
            InterfaceID.Messagebox.TEXT,
            InterfaceID.ChatLeft.TEXT,
            InterfaceID.Objectbox.TEXT,
            InterfaceID.ObjectboxDouble.TEXT
        };
        boolean foundCheck = false;
        for (int widgetId : dialogueTextWidgets)
        {
            Widget dialogueText = client.getWidget(widgetId);
            if (confirmRewardGuardianCheck(dialogueText))
            {
                foundCheck = true;
                break;
            }
        }
        if (!foundCheck)
        {
            Widget messageBox = client.getWidget(InterfaceID.Messagebox.UNIVERSE);
            if (messageBox != null)
            {
                for (Widget child : messageBox.getNestedChildren())
                {
                    if (confirmRewardGuardianCheck(child))
                    {
                        foundCheck = true;
                        break;
                    }
                }
            }
        }
        rewardGuardianCheckVisible = foundCheck;
    }

    private boolean confirmRewardGuardianCheck(Widget dialogueText)
    {
        if (dialogueText == null || dialogueText.isHidden())
        {
            return false;
        }
        OptionalInt parsedSearches = collectionLogCounterParser.parseRewardGuardianCheck(dialogueText.getText());
        if (!parsedSearches.isPresent())
        {
            return false;
        }

        int searches = parsedSearches.getAsInt();
        ActivityDefinition guardians = catalog.findByKillCountName("Guardians of the Rift");
        if (guardians != null)
        {
            service.cacheRateCount(guardians, searches, Instant.now());
            if (!rewardGuardianCheckVisible)
            {
                String formatted = NumberFormat.getIntegerInstance(Locale.ENGLISH).format(searches);
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                    "Kills To: GOTR dry counter refreshed - " + formatted + " searches.", null);
            }
        }
        return true;
    }

    private void openForInstallOrUpdate()
    {
        String acknowledged = configManager.getConfiguration(KillsToConfig.GROUP, ACKNOWLEDGED_VERSION);
        boolean firstInstall = acknowledged == null;
        boolean versionChanged = !VERSION.equals(acknowledged);
        boolean shouldOpen = (firstInstall && config.autoOpenOnInstall()) ||
            (!firstInstall && versionChanged && config.autoOpenOnUpdates());
        if (!versionChanged)
        {
            return;
        }
        configManager.setConfiguration(KillsToConfig.GROUP, ACKNOWLEDGED_VERSION, VERSION);
        if (shouldOpen)
        {
            panel.showUpdates();
            SwingUtilities.invokeLater(() -> clientToolbar.openPanel(navigationButton));
        }
    }

    private void activateForRewardClaim(String message)
    {
        if (client.getLocalPlayer() == null || message == null || !message.startsWith("You found some loot:"))
        {
            return;
        }
        int regionId = getStableRegionId();
        ActivityDefinition activity = null;
        if (regionId == 12588)
        {
            activity = catalog.findByKillCountName("Tempoross");
        }
        else if (regionId == 6461)
        {
            activity = catalog.findByKillCountName("Wintertodt");
        }
        else if (regionId == 14484)
        {
            activity = catalog.findByKillCountName("Guardians of the Rift");
        }
        if (activity != null)
        {
            service.activate(activity, false, Instant.now());
            if (regionId == 14484 || regionId == 12588 || regionId == 6461)
            {
                service.incrementKnownRateCount(activity, Instant.now());
            }
        }
    }

    private boolean isZalcanoFightActive()
    {
        int healthbarNpc = client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
        return healthbarNpc == NpcID.ZALCANO || healthbarNpc == NpcID.ZALCANO_WEAK;
    }

    private boolean isGuardiansOfTheRiftActive()
    {
        return client.getVarbitValue(VarbitID.GOTR_IS_PLAYING) != 0;
    }

    private ActivityDefinition findLoadedNpcActivity()
    {
        for (NPC npc : client.getTopLevelWorldView().npcs())
        {
            ActivityDefinition activity = catalog.findByNpcId(npc.getId());
            if (activity != null)
            {
                return activity;
            }
        }
        return null;
    }

    private int getStableRegionId()
    {
        return WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation()).getRegionID();
    }

}

