import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.killsto.model.ActivityDefinition;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

public final class ActivityCatalog
{
    private static final Type CATALOG_TYPE = new TypeToken<List<ActivityDefinition>>() { }.getType();

    private final List<ActivityDefinition> activities;
    private final Map<Integer, ActivityDefinition> byNpcId = new HashMap<>();
    private final Map<Integer, ActivityDefinition> byRegionId = new HashMap<>();
    private final Map<String, ActivityDefinition> byAlias = new HashMap<>();

    private ActivityCatalog(List<ActivityDefinition> activities)
    {
        this.activities = Collections.unmodifiableList(new ArrayList<>(activities));
        for (ActivityDefinition activity : activities)
        {
            for (Integer npcId : activity.getNpcIds())
            {
                byNpcId.put(npcId, activity);
            }
            for (Integer regionId : activity.getRegionIds())
            {
                byRegionId.put(regionId, activity);
            }
            byAlias.put(normalize(activity.getName()), activity);
            byAlias.put(normalize(activity.getKcKey()), activity);
            for (String alias : activity.getKcAliases())
            {
                byAlias.put(normalize(alias), activity);
            }
        }
    }

    public static ActivityCatalog load(Gson gson)
    {
        InputStream stream = ActivityCatalog.class.getResourceAsStream("/activity_catalog.json");
        if (stream == null)
        {
            throw new IllegalStateException("Missing activity_catalog.json");
        }

        try (InputStreamReader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
        {
            List<ActivityDefinition> definitions = gson.fromJson(reader, CATALOG_TYPE);
            if (definitions == null || definitions.isEmpty())
            {
                throw new IllegalStateException("Activity catalog is empty");
            }
            return new ActivityCatalog(definitions);
        }
        catch (IOException ex)
        {
            throw new IllegalStateException("Unable to read activity catalog", ex);
        }
    }

    public List<ActivityDefinition> getActivities()
    {
        return activities;
    }

    public ActivityDefinition findByNpcId(int npcId)
    {
        return byNpcId.get(npcId);
    }

    public ActivityDefinition findByRegionId(int regionId)
    {
        return byRegionId.get(regionId);
    }

    public ActivityDefinition findByKillCountName(String name)
    {
        return byAlias.get(normalize(name));
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.trim().toLowerCase(Locale.ENGLISH);
    }
}

