public final class ActivityDrop
{
    private int itemId;
    private String name;
    private int numerator;
    private int denominator;
    private String rateDisplay;
    private boolean variableRate;
    private Double dryRate;
    private String wikiUrl;

    public int getItemId()
    {
        return itemId;
    }

