    {
        return denominator;
    }

    public String getWikiUrl()
    {
        return wikiUrl;
    }

    public double probability()
    {
        return (double) numerator / denominator;
    }

    public double normalizedRate()
    {
        return (double) denominator / numerator;
    }

    public boolean isVariableRate()
    {
        return variableRate;
    }

    public boolean hasDryRate()
    {
        return !variableRate || dryRate != null && dryRate > 0D;
    }

