public final class DropProgress
{
    private final ActivityDrop drop;
    private final long killsDifference;
    private final double cumulativeChance;
    private final boolean countKnown;

    public DropProgress(ActivityDrop drop, long killsDifference, double cumulativeChance)
    {
        this(drop, killsDifference, cumulativeChance, true);
    }

    public DropProgress(ActivityDrop drop, long killsDifference, double cumulativeChance, boolean countKnown)
    {
        this.drop = drop;
        this.killsDifference = killsDifference;
        this.cumulativeChance = cumulativeChance;
        this.countKnown = countKnown;
    }

    public ActivityDrop getDrop()
    {
        return drop;
    }

    public long getKillsDifference()
    {
        return killsDifference;
    }

    public double getCumulativeChance()
    {
        return cumulativeChance;
    }

    public String killsMetric()
    {
        return Math.abs(killsDifference) + (killsDifference >= 0 ? " to rate" : " over rate");
    }

    public boolean isCountKnown()
    {
        return countKnown;
    }

    public String progressMetric(ProgressUnit unit)
    {
        if (drop.isVariableRate())
        {
            return "personal rate varies";
        }
        if (!countKnown)
        {
            return "? " + unit.amountLabel(2) + " to rate";
        }
        return Math.abs(killsDifference) + " " + unit.amountLabel(killsDifference) +
            (killsDifference >= 0 ? " to rate" : " over rate");
    }

    public boolean hasExactRate()
    {
        return !drop.isVariableRate();
    }
}

