package com.killsto.service;

import java.util.OptionalInt;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

public final class CollectionLogCounterParser
{
    private static final Pattern LINE_BREAK = Pattern.compile("<br\\s*/?>", Pattern.CASE_INSENSITIVE);
    private static final Pattern RIFTS_SEARCHES = Pattern.compile(
        "^\\s*Rifts searches\\s*:\\s*([0-9,]+)\\s*$", Pattern.CASE_INSENSITIVE);
    private static final Pattern REWARD_PERMITS_CLAIMED = Pattern.compile(
        "^\\s*Reward permits claimed\\s*:\\s*([0-9,]+)\\s*$", Pattern.CASE_INSENSITIVE);
    private static final Pattern REWARDS_CLAIMED = Pattern.compile(
        "^\\s*Rewards claimed\\s*:\\s*([0-9,]+)\\s*$", Pattern.CASE_INSENSITIVE);
    private static final Pattern REWARD_GUARDIAN_SEARCHES = Pattern.compile(
        "You have searched the rift\\s+([0-9,]+)\\s+times", Pattern.CASE_INSENSITIVE);

    public OptionalInt parseRiftsSearches(String widgetText)
    {
        if (widgetText == null)
        {
            return OptionalInt.empty();
        }

        Matcher matcher = RIFTS_SEARCHES.matcher(normalize(widgetText));
        if (!matcher.matches())
        {
            return OptionalInt.empty();
        }

        try
        {
            return OptionalInt.of(Integer.parseInt(matcher.group(1).replace(",", "")));
        }
        catch (NumberFormatException ignored)
        {
            return OptionalInt.empty();
        }
    }

    public OptionalInt parseRewardGuardianCheck(String widgetText)
    {
        if (widgetText == null)
        {
            return OptionalInt.empty();
        }

        Matcher matcher = REWARD_GUARDIAN_SEARCHES.matcher(normalize(widgetText));
        if (!matcher.find())
        {
            return OptionalInt.empty();
        }

        try
        {
            return OptionalInt.of(Integer.parseInt(matcher.group(1).replace(",", "")));
        }
        catch (NumberFormatException ignored)
        {
            return OptionalInt.empty();
        }
    }

    public OptionalInt parseRewardPermitsClaimed(String widgetText)
    {
        if (widgetText == null)
        {
            return OptionalInt.empty();
        }

        Matcher matcher = REWARD_PERMITS_CLAIMED.matcher(normalize(widgetText));
        if (!matcher.matches())
        {
            return OptionalInt.empty();
        }

        try
        {
            return OptionalInt.of(Integer.parseInt(matcher.group(1).replace(",", "")));
        }
        catch (NumberFormatException ignored)
        {
            return OptionalInt.empty();
        }
    }

    public OptionalInt parseRewardsClaimed(String widgetText)
    {
        if (widgetText == null)
        {
            return OptionalInt.empty();
        }

        Matcher matcher = REWARDS_CLAIMED.matcher(normalize(widgetText));
        if (!matcher.matches())
        {
            return OptionalInt.empty();
        }

        try
        {
            return OptionalInt.of(Integer.parseInt(matcher.group(1).replace(",", "")));
        }
        catch (NumberFormatException ignored)
        {
            return OptionalInt.empty();
        }
    }

    private static String normalize(String widgetText)
    {
        String withLineBreakSpaces = LINE_BREAK.matcher(widgetText).replaceAll(" ");
        return Text.removeTags(withLineBreakSpaces).replace('\u00A0', ' ').trim();
    }
}

package com.killsto.service;

import com.killsto.model.SyncState;
import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.client.config.ConfigManager;

public final class CollectionProgressStore
{
    private static final String GROUP = "killsto-data";
    private static final String OBTAINED_PREFIX = "obtainedItemIds.";
    private static final String LAST_SYNC_PREFIX = "lastSync.";
    private static final String RUNEPROFILE_OBTAINED_PREFIX = "runeProfileObtainedItemIds.";
    private static final String RUNEPROFILE_LAST_SYNC_PREFIX = "runeProfileLastSync.";

    private final ConfigManager configManager;

    public CollectionProgressStore(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    public Set<Integer> loadObtainedItemIds(String activityKey)
    {
        return loadItemIds(OBTAINED_PREFIX + activityKey);
    }

    public Set<Integer> loadRuneProfileItemIds(String activityKey)
    {
        return loadItemIds(RUNEPROFILE_OBTAINED_PREFIX + activityKey);
    }

    private Set<Integer> loadItemIds(String key)
    {
        String value = configManager.getRSProfileConfiguration(GROUP, key);
        if (value == null || value.trim().isEmpty())
        {
            return Collections.emptySet();
        }
        Set<Integer> result = new HashSet<>();
        for (String part : value.split(","))
        {
            try
            {
                result.add(Integer.parseInt(part.trim()));
            }
            catch (NumberFormatException ignored)
            {
                // Preserve usable values if one cached token is corrupt.
            }
        }
        return result;
    }

    public void saveActivityPage(String activityKey, Set<Integer> obtainedItemIds, Instant now)
    {
        saveItemIds(OBTAINED_PREFIX + activityKey, LAST_SYNC_PREFIX + activityKey, obtainedItemIds, now);
    }

    public void saveRuneProfilePage(String activityKey, Set<Integer> obtainedItemIds, Instant now)
    {
        saveItemIds(
            RUNEPROFILE_OBTAINED_PREFIX + activityKey,
            RUNEPROFILE_LAST_SYNC_PREFIX + activityKey,
            obtainedItemIds,
            now);
    }

    public void clearActivity(String activityKey)
    {
        configManager.unsetRSProfileConfiguration(GROUP, OBTAINED_PREFIX + activityKey);
        configManager.unsetRSProfileConfiguration(GROUP, LAST_SYNC_PREFIX + activityKey);
        configManager.unsetRSProfileConfiguration(GROUP, RUNEPROFILE_OBTAINED_PREFIX + activityKey);
        configManager.unsetRSProfileConfiguration(GROUP, RUNEPROFILE_LAST_SYNC_PREFIX + activityKey);
    }

    private void saveItemIds(String itemsKey, String syncKey, Set<Integer> obtainedItemIds, Instant now)
    {
        StringBuilder value = new StringBuilder();
        for (Integer itemId : new TreeSet<>(obtainedItemIds))
        {
            if (value.length() > 0)
            {
                value.append(',');
            }
            value.append(itemId);
        }
        configManager.setRSProfileConfiguration(GROUP, itemsKey, value.toString());
        configManager.setRSProfileConfiguration(GROUP, syncKey, now.toString());
    }

    public Instant getLastSync(String activityKey)
    {
        return getLastSyncForKey(LAST_SYNC_PREFIX + activityKey);
    }

    public Instant getRuneProfileLastSync(String activityKey)
    {
        return getLastSyncForKey(RUNEPROFILE_LAST_SYNC_PREFIX + activityKey);
    }

    private Instant getLastSyncForKey(String key)
    {
        String value = configManager.getRSProfileConfiguration(GROUP, key);
        if (value == null)
        {
            return null;
        }
        try
        {
            return Instant.parse(value);
        }
        catch (RuntimeException ignored)
        {
            return null;
        }
    }

    public SyncState getSyncState(String activityKey, Instant now, int staleDays)
    {
        return syncState(getLastSync(activityKey), now, staleDays);
    }

    public SyncState getRuneProfileSyncState(String activityKey, Instant now, int staleDays)
    {
        return syncState(getRuneProfileLastSync(activityKey), now, staleDays);
    }

    private static SyncState syncState(Instant lastSync, Instant now, int staleDays)
    {
        if (lastSync == null)
        {
            return SyncState.NOT_SYNCED;
        }
        return lastSync.plus(Duration.ofDays(staleDays)).isBefore(now)
            ? SyncState.STALE : SyncState.SYNCED;
    }
}

package com.killsto.service;

import com.killsto.model.ActivityDefinition;
import com.killsto.model.ActivityDrop;
import com.killsto.model.ActivityDisplayModel;
import com.killsto.model.DropProgress;
import com.killsto.model.OwnershipSource;
import com.killsto.model.SyncState;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public final class DisplayModelFactory
{
    public ActivityDisplayModel create(
        ActivityDefinition activity,
        Integer killCount,
        Set<Integer> obtainedItemIds,
        SyncState syncState,
        boolean active)
    {
        Integer rateCount = activity.getDisplayUnit() == activity.getRateUnit() ? killCount : null;
        return create(activity, killCount, rateCount, obtainedItemIds, syncState, active);
    }

    public ActivityDisplayModel create(
        ActivityDefinition activity,
        Integer activityCount,
        Integer rateCount,
        Set<Integer> obtainedItemIds,
        SyncState syncState,
        boolean active)
    {
        OwnershipSource source = syncState == SyncState.NOT_SYNCED
            ? OwnershipSource.NONE : OwnershipSource.LOCAL;
        return create(activity, activityCount, rateCount, obtainedItemIds, syncState, source, active);
    }

    public ActivityDisplayModel create(
        ActivityDefinition activity,
        Integer activityCount,
        Integer rateCount,
        Set<Integer> obtainedItemIds,
        SyncState syncState,
        OwnershipSource ownershipSource,
        boolean active)
    {
        List<DropProgress> allMissing = new ArrayList<>();
        if (syncState != SyncState.NOT_SYNCED)
        {
            Set<Integer> obtained = obtainedItemIds == null ? new HashSet<>() : obtainedItemIds;
            for (ActivityDrop drop : activity.getDrops())
            {
                if (!obtained.contains(drop.getItemId()))
                {
                    allMissing.add(progress(drop, rateCount));
                }
            }
            allMissing.sort(Comparator.comparingDouble((DropProgress progress) ->
                progress.getDrop().normalizedRate()).reversed());
        }

        long dryStep = dryStep(rateCount, allMissing);
        int dryTier = (int) Math.min(5L, dryStep);
        String dryMessage = DryJokeLibrary.forActivity(activity.getKey(), dryTier, dryStep);

        return new ActivityDisplayModel(
            activity,
            activityCount,
            rateCount,
            allMissing,
            syncState,
            ownershipSource,
            dryTier,
            dryMessage,
            active);
    }

    private static DropProgress progress(ActivityDrop drop, Integer killCount)
    {
        if (killCount == null)
        {
            return new DropProgress(drop, Math.round(drop.normalizedRate()), 0D, false);
        }
        long difference = Math.round(drop.normalizedRate()) - killCount;
        double chance = 1D - Math.pow(1D - drop.probability(), killCount);
        return new DropProgress(drop, difference, chance);
    }

    static int dryTier(Integer killCount, List<DropProgress> missing)
    {
        return (int) Math.min(5L, dryStep(killCount, missing));
    }

    private static long dryStep(Integer killCount, List<DropProgress> missing)
    {
        if (killCount == null || missing.isEmpty())
        {
            return 0;
        }
        return missing.stream()
            .filter(progress -> progress.getDrop().hasDryRate())
            .mapToLong(progress -> dryStep(
                killCount, progress.getDrop().normalizedDryRate()))
            .max()
            .orElse(0L);
    }

    private static long dryStep(int count, double rate)
    {
        if (rate <= 0D || count <= rate)
        {
            return 0;
        }
        double interval = Math.max(1D, rate / 5D);
        return 1L + (long) Math.floor((count - rate) / interval);
    }
}

package com.killsto.service;

final class DryJokeLibrary
{
    private static final String[][] JOKES = {
        {
            "RNG is running fashionably late.",
            "Any kill now. Probably.",
            "\"Just one more,\" said the liar.",
            "Luck took the scenic route.",
            "RNG says it is on the way."
        },
        {
            "Your RNG has logged out.",
            "The spoon has filed for divorce.",
            "Probability sends its regards.",
            "Have you tried turning your luck off and on again?",
            "Dry enough to need lip balm."
        },
        {
            "Dry as the Sahara, with worse loot.",
            "The Kharidian Desert feels humid now.",
            "Your drop needs a rain dance.",
            "The desert wants its dryness back.",
            "Even sand looks hydrated beside you."
        },
        {
            "Your log is a hostage situation.",
            "RNG has chosen emotional damage.",
            "Even Hans has started checking on you.",
            "Even the Wiki feels awkward.",
            "This grind has developed a personality."
        },
        {
            "Scientists are studying your account.",
            "This drought has been named after you.",
            "Your RNG needs an exorcism.",
            "The drop is now legally a myth.",
            "You have outlived the probability model.",
            "Guinness called. Do another kill.",
            "The loot exists in another timeline.",
            "Please report your RNG as missing.",
            "Your spoon was never manufactured.",
            "Respectfully, what the actual RNG?"
        }
    };

    private DryJokeLibrary()
    {
    }

    static String forActivity(String activityKey, int dryTier)
    {
        return forActivity(activityKey, dryTier, dryTier);
    }

    static String forActivity(String activityKey, int dryTier, long dryStep)
    {
        if (dryTier <= 0)
        {
            return null;
        }
        int tierIndex = Math.min(dryTier, JOKES.length) - 1;
        String[] tierJokes = JOKES[tierIndex];
        int jokeIndex = (int) Math.floorMod(
            (long) activityKey.hashCode() + dryStep - 1L, tierJokes.length);
        return "Dry " + (tierIndex + 1) + " · " + tierJokes[jokeIndex];
    }
}

package com.killsto.service;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class KillCountParser
{
    private static final Pattern KC_PATTERN = Pattern.compile(
        "Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?" +
        "(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?" +
        "(?:count )?)is: ?<col=[0-9a-f]{6}>(?<kc>[0-9,]+)</col>",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern RIFTS_CLOSED_PATTERN = Pattern.compile(
        "Amount of Rifts you have closed: <col=[0-9a-f]{6}>([0-9,]+)</col>\\.",
        Pattern.CASE_INSENSITIVE);

    public Optional<Result> parse(String message)
    {
        if (message == null)
        {
            return Optional.empty();
        }
        Matcher riftsMatcher = RIFTS_CLOSED_PATTERN.matcher(message);
        if (riftsMatcher.find())
        {
            return Optional.of(new Result(
                "Guardians of the Rift",
                Integer.parseInt(riftsMatcher.group(1).replace(",", ""))));
        }
        Matcher matcher = KC_PATTERN.matcher(message);
        if (!matcher.find())
        {
            return Optional.empty();
        }
        return Optional.of(new Result(
            matcher.group("boss").trim(),
            Integer.parseInt(matcher.group("kc").replace(",", ""))));
    }

    public static final class Result
    {
        private final String activityName;
        private final int killCount;

        Result(String activityName, int killCount)
        {
            this.activityName = activityName;
            this.killCount = killCount;
        }

        public String getActivityName()
        {
            return activityName;
        }

        public int getKillCount()
        {
            return killCount;
        }
    }
}

package com.killsto.service;

import com.killsto.KillsToConfig;
import com.killsto.model.ActivityDefinition;
import com.killsto.model.ActivityDisplayModel;
import com.killsto.model.OwnershipSource;
import com.killsto.model.SyncState;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Consumer;
import net.runelite.client.config.ConfigManager;

public final class KillsToService
{
    private static final String DATA_GROUP = "killsto-data";
    private static final String RATE_COUNT_PREFIX = "rateCount.";
    private static final String RATE_COUNT_SCHEMA_PREFIX = "rateCountSchema.";
    private static final String AUTHORITATIVE_RATE_SCHEMA = "1";

    private final KillsToConfig config;
    private final ConfigManager configManager;
    private final CollectionProgressStore progressStore;
    private final DisplayModelFactory modelFactory = new DisplayModelFactory();
    private final ActivitySession session = new ActivitySession();
    private final List<Consumer<ActivityDisplayModel>> listeners = new ArrayList<>();

    private ActivityDefinition activity;
    private Integer killCount;
    private Integer rateCount;
    private boolean encounterActive;

    public KillsToService(KillsToConfig config, ConfigManager configManager)
    {
        this.config = config;
        this.configManager = configManager;
        this.progressStore = new CollectionProgressStore(configManager);
    }

    public void addListener(Consumer<ActivityDisplayModel> listener)
    {
        listeners.add(listener);
    }

    public void activate(ActivityDefinition nextActivity, boolean active, Instant now)
    {
        boolean changedActivity = activity == null || !activity.getKey().equals(nextActivity.getKey());
        activity = nextActivity;
        encounterActive = active;
        if (changedActivity)
        {
            killCount = readKillCount(nextActivity);
            rateCount = readRateCount(nextActivity, killCount);
        }
        rebuild(now);
    }

    public void updateKillCount(ActivityDefinition nextActivity, int newKillCount, Instant now)
    {
        activity = nextActivity;
        killCount = newKillCount;
        rateCount = readRateCount(nextActivity, newKillCount);
        encounterActive = false;
        configManager.setRSProfileConfiguration("killcount", nextActivity.getKcKey().toLowerCase(Locale.ENGLISH), newKillCount);
        rebuild(now);
    }

    public void updateRateCount(ActivityDefinition nextActivity, int newRateCount, Instant now)
    {
        if (activity == null || !activity.getKey().equals(nextActivity.getKey()))
        {
            activity = nextActivity;
            killCount = readKillCount(nextActivity);
        }
        if (rateCount != null && rateCount == newRateCount)
        {
            return;
        }
        rateCount = newRateCount;
        configManager.setRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_PREFIX + nextActivity.getKey(), newRateCount);
        configManager.setRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_SCHEMA_PREFIX + nextActivity.getKey(), AUTHORITATIVE_RATE_SCHEMA);
        rebuild(now);
    }

    public void cacheRateCount(ActivityDefinition definition, int newRateCount, Instant now)
    {
        Integer storedCount = configManager.getRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_PREFIX + definition.getKey(), Integer.class);
        String storedSchema = configManager.getRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_SCHEMA_PREFIX + definition.getKey(), String.class);
        if (Integer.valueOf(newRateCount).equals(storedCount) && AUTHORITATIVE_RATE_SCHEMA.equals(storedSchema))
        {
            return;
        }
        configManager.setRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_PREFIX + definition.getKey(), newRateCount);
        configManager.setRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_SCHEMA_PREFIX + definition.getKey(), AUTHORITATIVE_RATE_SCHEMA);
        if (activity != null && activity.getKey().equals(definition.getKey()))
        {
            rateCount = newRateCount;
            rebuild(now);
        }
    }

    public boolean incrementKnownRateCount(ActivityDefinition definition, Instant now)
    {
        Integer currentCount;
        if (activity != null && activity.getKey().equals(definition.getKey()))
        {
            currentCount = rateCount;
        }
        else
        {
            currentCount = readRateCount(definition, null);
        }
        if (currentCount == null)
        {
            return false;
        }

        cacheRateCount(definition, currentCount + 1, now);
        return true;
    }

    public void syncCollectionLog(ActivityDefinition definition, Set<Integer> obtainedItemIds, Instant now)
    {
        progressStore.saveActivityPage(definition.getKey(), obtainedItemIds, now);
        if (activity != null && activity.getKey().equals(definition.getKey()))
        {
            rebuild(now);
        }
    }

    public void syncRuneProfileCollectionLog(
        ActivityDefinition definition,
        Set<Integer> obtainedItemIds,
        Instant now)
    {
        progressStore.saveRuneProfilePage(definition.getKey(), obtainedItemIds, now);
        if (activity != null && activity.getKey().equals(definition.getKey()))
        {
            rebuild(now);
        }
    }

    public void discardRateCount(ActivityDefinition definition)
    {
        configManager.unsetRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_PREFIX + definition.getKey());
        configManager.unsetRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_SCHEMA_PREFIX + definition.getKey());
        if (activity != null && activity.getKey().equals(definition.getKey()))
        {
            rateCount = null;
        }
    }

    public void setEncounterActive(boolean active, Instant now)
    {
        if (activity == null || encounterActive == active)
        {
            return;
        }
        encounterActive = active;
        rebuild(now);
    }

    public void refresh(Instant now)
    {
        if (activity != null)
        {
            rebuild(now);
        }
    }

    public ActivityDisplayModel getModel()
    {
        return session.getModel();
    }

    public ActivityDefinition clearActiveCollectionLogCaches(Instant now)
    {
        if (activity == null)
        {
            return null;
        }
        ActivityDefinition clearedActivity = activity;
        progressStore.clearActivity(clearedActivity.getKey());
        rebuild(now);
        return clearedActivity;
    }

    public boolean isOverlayVisible(Instant now)
    {
        return config.showOverlay() && session.isOverlayVisible(now);
    }

    public void clear()
    {
        activity = null;
        killCount = null;
        rateCount = null;
        encounterActive = false;
        session.clear();
        notifyListeners(null);
    }

    private void rebuild(Instant now)
    {
        SyncState localState = progressStore.getSyncState(activity.getKey(), now, config.staleSyncDays());
        SyncState syncState = localState;
        OwnershipSource source = localState == SyncState.NOT_SYNCED
            ? OwnershipSource.NONE : OwnershipSource.LOCAL;
        Set<Integer> obtainedItemIds = progressStore.loadObtainedItemIds(activity.getKey());
        if (config.enableRuneProfileFallback() && localState != SyncState.SYNCED)
        {
            SyncState remoteState = progressStore.getRuneProfileSyncState(
                activity.getKey(), now, config.staleSyncDays());
            if (remoteState == SyncState.SYNCED ||
                (localState == SyncState.NOT_SYNCED && remoteState == SyncState.STALE))
            {
                syncState = remoteState;
                source = OwnershipSource.RUNEPROFILE;
                obtainedItemIds = progressStore.loadRuneProfileItemIds(activity.getKey());
            }
        }
        ActivityDisplayModel model = modelFactory.create(
            activity,
            killCount,
            rateCount,
            obtainedItemIds,
            syncState,
            source,
            encounterActive);
        session.update(model, encounterActive, now, Duration.ofSeconds(config.visibilitySeconds()));
        notifyListeners(model);
    }

    private Integer readKillCount(ActivityDefinition definition)
    {
        return configManager.getRSProfileConfiguration(
            "killcount", definition.getKcKey().toLowerCase(Locale.ENGLISH), Integer.class);
    }

    private Integer readRateCount(ActivityDefinition definition, Integer activityCount)
    {
        if (definition.getDisplayUnit() == definition.getRateUnit())
        {
            return activityCount;
        }
        String schema = configManager.getRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_SCHEMA_PREFIX + definition.getKey(), String.class);
        if (!AUTHORITATIVE_RATE_SCHEMA.equals(schema))
        {
            return null;
        }
        return configManager.getRSProfileConfiguration(
            DATA_GROUP, RATE_COUNT_PREFIX + definition.getKey(), Integer.class);
    }

    private void notifyListeners(ActivityDisplayModel model)
    {
        for (Consumer<ActivityDisplayModel> listener : new ArrayList<>(listeners))
        {
            listener.accept(model);
        }
    }
}

package com.killsto.service;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.killsto.model.ActivityDefinition;
import com.killsto.model.ActivityDrop;
import java.io.IOException;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

public final class RuneProfileClient
{
    private static final HttpUrl API_BASE = HttpUrl.parse("https://api.runeprofile.com/v1");
    private static final String USER_AGENT =
        "Kills-To-RuneLite/0.4.4 (https://github.com/xboxnuker-rgb/KC-to)";

    private final OkHttpClient httpClient;
    private final Gson gson;

    @Inject
    public RuneProfileClient(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    public void fetchCollectionLogPage(
        String username,
        ActivityDefinition activity,
        ResultListener listener)
    {
        Set<Integer> catalogItemIds = new HashSet<>();
        for (ActivityDrop drop : activity.getDrops())
        {
            catalogItemIds.add(drop.getItemId());
        }
        Request request = new Request.Builder()
            .url(buildUrl(username, activity))
            .header("User-Agent", USER_AGENT)
            .get()
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                listener.onResult(Result.error());
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response closedResponse = response)
                {
                    if (closedResponse.code() == 404)
                    {
                        listener.onResult(Result.notFound());
                        return;
                    }
                    if (closedResponse.code() == 429)
                    {
                        listener.onResult(Result.rateLimited());
                        return;
                    }
                    ResponseBody body = closedResponse.body();
                    if (!closedResponse.isSuccessful() || body == null)
                    {
                        listener.onResult(Result.error());
                        return;
                    }
                    listener.onResult(parsePage(body.string(), catalogItemIds));
                }
                catch (IOException | JsonParseException exception)
                {
                    listener.onResult(Result.error());
                }
            }
        });
    }

    static HttpUrl buildUrl(String username, ActivityDefinition activity)
    {
        return API_BASE.newBuilder()
            .addPathSegment("accounts")
            .addPathSegment(username)
            .addPathSegment("collection-log")
            .addPathSegment(activity.getCollectionLogTab())
            .addPathSegment(activity.getName())
            .build();
    }

    Result parsePage(String json, Set<Integer> catalogItemIds)
    {
        PageResponse page = gson.fromJson(json, PageResponse.class);
        if (page == null || page.items == null)
        {
            return Result.error();
        }
        Set<Integer> obtained = new HashSet<>();
        for (PageItem item : page.items)
        {
            if (item != null && item.quantity > 0 && catalogItemIds.contains(item.id))
            {
                obtained.add(item.id);
            }
        }
        return Result.success(obtained);
    }

    public interface ResultListener
    {
        void onResult(Result result);
    }

    public enum Status
    {
        SUCCESS,
        NOT_FOUND,
        RATE_LIMITED,
        ERROR
    }

    public static final class Result
    {
        private final Status status;
        private final Set<Integer> obtainedItemIds;

        private Result(Status status, Set<Integer> obtainedItemIds)
        {
            this.status = status;
            this.obtainedItemIds = Collections.unmodifiableSet(new HashSet<>(obtainedItemIds));
        }

        public static Result success(Set<Integer> obtainedItemIds)
        {
            return new Result(Status.SUCCESS, obtainedItemIds);
        }

        public static Result notFound()
        {
            return new Result(Status.NOT_FOUND, Collections.emptySet());
        }

        public static Result rateLimited()
        {
            return new Result(Status.RATE_LIMITED, Collections.emptySet());
        }

        public static Result error()
        {
            return new Result(Status.ERROR, Collections.emptySet());
        }

        public Status getStatus()
        {
            return status;
        }

        public Set<Integer> getObtainedItemIds()
        {
            return obtainedItemIds;
        }
    }

    private static final class PageResponse
    {
        private List<PageItem> items;
    }

    private static final class PageItem
    {
        private int id;
        private int quantity;
    }
}

package com.killsto.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TextComponent;

public final class DropRowComponent implements LayoutableRenderableEntity
{
    private static final int ICON_GAP = 4;

    private final BufferedImage image;
    private final List<String> lines;
    private final Rectangle bounds = new Rectangle();
    private Point preferredLocation = new Point();
    private Dimension preferredSize = new Dimension();

    public DropRowComponent(BufferedImage image, List<String> lines)
    {
        this.image = image;
        this.lines = lines;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        FontMetrics metrics = graphics.getFontMetrics();
        int lineHeight = metrics.getHeight();
        int imageWidth = image == null ? 0 : image.getWidth() + ICON_GAP;
        int imageHeight = image == null ? 0 : image.getHeight();
        int textHeight = lines.size() * lineHeight;
        int height = Math.max(imageHeight, textHeight);
        int contentWidth = imageWidth;

        if (image != null)
        {
            int imageY = preferredLocation.y + Math.max(0, (height - image.getHeight()) / 2);
            graphics.drawImage(image, preferredLocation.x, imageY, null);
        }

        TextComponent text = new TextComponent();
        for (int index = 0; index < lines.size(); index++)
        {
            String line = lines.get(index);
            text.setText(line);
            text.setPosition(preferredLocation.x + imageWidth,
                preferredLocation.y + ((index + 1) * lineHeight));
            Dimension textSize = text.render(graphics);
            contentWidth = Math.max(contentWidth, imageWidth + textSize.width);
        }

        int width = preferredSize.width > 0 ? preferredSize.width : contentWidth;
        Dimension dimension = new Dimension(width, height);
        bounds.setLocation(preferredLocation);
        bounds.setSize(dimension);
        return dimension;
    }

    @Override
    public Rectangle getBounds()
    {
        return bounds;
    }

    @Override
    public void setPreferredLocation(Point position)
    {
        preferredLocation = position;
    }

    @Override
    public void setPreferredSize(Dimension dimension)
    {
        preferredSize = dimension;
    }
}

