    public void updateModel(ActivityDisplayModel model)
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            SwingUtilities.invokeLater(() -> updateModel(model));
            return;
        }

        rows.removeAll();
        if (model == null)
        {
            activityLabel.setText("No recent activity");
            kcLabel.setText("KC ?");
            rateCountLabel.setVisible(false);
            stateLabel.setText("Enter a supported boss encounter to begin.");
            syncLabel.setText("Local Collection Log: not synced");
        }
        else
        {
            activityLabel.setText((model.isActive() ? "Active: " : "Last activity: ") + model.getActivity().getName());
            kcLabel.setText(model.getKillCountText());
            boolean separateRateCount = model.getActivity().getDisplayUnit() != model.getActivity().getRateUnit();
            rateCountLabel.setVisible(separateRateCount);
            rateCountLabel.setText(separateRateCount ? "Dry counter: " + model.getRateCountText() : "");
            renderRows(model);
            renderSyncState(model.getSyncState(), model.getOwnershipSource());
        }
        rows.revalidate();
        rows.repaint();
    }

    public void showUpdates()
    {
        tabs.setSelectedIndex(1);
    }

    public void setRuneProfileStatus(String status)
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            SwingUtilities.invokeLater(() -> setRuneProfileStatus(status));
            return;
        }
        runeProfileLabel.setText("<html>RuneProfile fallback:<br>" + status + "</html>");
    }

    private void renderRows(ActivityDisplayModel model)
    {
        if (model.getSyncState() == SyncState.NOT_SYNCED)
        {
            stateLabel.setText("<html>Sync your Collection Log before<br>missing items are shown.</html>");
            return;
        }
        if (model.getMissing().isEmpty())
        {
            stateLabel.setText("Collection complete");
            return;
        }
        stateLabel.setText(model.getMissing().size() + " missing");
        for (DropProgress progress : model.getMissing())
        {
            JLabel row = new JLabel(formatRow(progress, model.getActivity().getRateUnit()));
            row.setAlignmentX(Component.LEFT_ALIGNMENT);
            if (config.showItemIcons())
            {
                AsyncBufferedImage image = itemManager.getImage(progress.getDrop().getItemId());
                if (image != null)
                {
                    image.addTo(row);
                }
            }
            rows.add(row);
        }
        if (config.showDryJokes() && model.getDryMessage() != null)
        {
            JLabel joke = new JLabel("<html><i>" + model.getDryMessage() + "</i></html>");
            joke.setForeground(new Color(231, 178, 62));
            rows.add(joke);
        }
    }

    private String formatRow(DropProgress progress, ProgressUnit progressUnit)
    {
        StringBuilder result = new StringBuilder("<html>");
        if (config.showItemNames())
        {
            result.append(progress.getDrop().getName());
        }
        if (config.showWikiRates())
        {
            result.append(" <font color='#a8a8a8'>").append(progress.getDrop().rateText()).append("</font>");
        }
        boolean showMetrics = !progress.getDrop().isVariableRate() || config.showVariableRateMetrics();
        if (showMetrics &&
            (config.metricMode() == MetricMode.KILLS_TO || config.metricMode() == MetricMode.BOTH))
        {
            result.append("<br>").append(progress.progressMetric(progressUnit));
        }
        if (showMetrics &&
            (config.metricMode() == MetricMode.CUMULATIVE_CHANCE || config.metricMode() == MetricMode.BOTH))
        {
            result.append(config.metricMode() == MetricMode.BOTH ? " · " : "<br>")
                .append(progress.hasExactRate()
                    ? (progress.isCountKnown() ? PERCENT.format(progress.getCumulativeChance()) : "chance ?")
                    : "chance varies");
        }
        return result.append("</html>").toString();
    }

    private void renderSyncState(SyncState state, OwnershipSource source)
    {
        syncLabel.setText(syncStatusText(state, source));
        if (state == SyncState.NOT_SYNCED)
        {
            syncLabel.setForeground(Color.ORANGE);
        }
        else if (state == SyncState.STALE)
        {
            syncLabel.setForeground(Color.ORANGE);
        }
        else
        {
            syncLabel.setForeground(Color.WHITE);
        }
    }

    static String syncStatusText(SyncState state)
    {
        OwnershipSource source = state == SyncState.NOT_SYNCED
            ? OwnershipSource.NONE : OwnershipSource.LOCAL;
        return syncStatusText(state, source);
    }

    static String syncStatusText(SyncState state, OwnershipSource source)
    {
        String provider = source == OwnershipSource.RUNEPROFILE
            ? "RuneProfile Collection Log" : "Local Collection Log";
        if (state == SyncState.NOT_SYNCED)
        {
            return "Local Collection Log: not synced";
        }
        if (state == SyncState.STALE)
        {
            return provider + ": stale";
        }
        return provider + ": synced";
    }

    private JPanel createStatusTab()
    {
        JPanel panel = verticalPanel();
        panel.setBorder(BorderFactory.createEmptyBorder(8, 3, 3, 3));
        syncLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.add(syncLabel);
        panel.add(new JLabel("KC source: RuneLite profile cache"));
        panel.add(new JLabel("Ownership source: local first"));
        setRuneProfileStatus(config.enableRuneProfileFallback() ? "enabled" : "off");
        panel.add(runeProfileLabel);
        panel.add(Box.createRigidArea(new Dimension(0, 8)));
        JButton sync = new JButton("Sync open page");
        sync.setToolTipText("Open a supported Collection Log page, then click to capture it locally");
        sync.addActionListener(event -> syncAction.run());
        sync.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.add(sync);
        return panel;
    }

    private JPanel createUpdatesTab()
    {
        JPanel panel = verticalPanel();
        panel.setBorder(BorderFactory.createEmptyBorder(8, 3, 3, 3));
        panel.add(new JLabel("<html><b>Kills To 0.4.4</b></html>"));
        panel.add(new JLabel("<html>Completed every supported<br>Collection Log catalog, including<br>the new Immaculate mole skin.</html>"));
        panel.add(Box.createRigidArea(new Dimension(0, 6)));
        panel.add(new JLabel("Catalog: starter-2026.09"));
        panel.add(new JLabel("Reviewed: 6 September 2026"));
        return panel;
    }

    private JPanel createInfoTab()
    {
        JPanel panel = verticalPanel();
        panel.setBorder(BorderFactory.createEmptyBorder(8, 3, 3, 3));
        panel.add(new JLabel("<html><b>Kills to rate</b><br>Wiki rate minus current KC.</html>"));
        panel.add(new JLabel("<html><br><b>Cumulative chance</b><br>1 - (1 - p)<sup>KC</sup></html>"));
        panel.add(new JLabel("<html><br>Only retrospective information is shown.<br>No combat prompts or prediction.</html>"));
        panel.add(new JLabel("<html><br>RuneProfile is optional. When enabled,<br>your RSN is sent only when local data<br>is missing or stale. Local stays first.</html>"));
        return panel;
