import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class IconAssetsTest
{
    @Test
    public void pluginHubIconMeetsDimensionAndTransparencyRules() throws IOException
    {
        File file = new File("icon.png");
        assertTrue(file.isFile());
        BufferedImage image = ImageIO.read(file);
        assertNotNull(image);
        assertEquals(48, image.getWidth());
        assertEquals(48, image.getHeight());
        assertTrue(image.getColorModel().hasAlpha());
        assertTrue(hasTransparentPixel(image));
    }

    @Test
    public void sidebarIconIsCrispNativeSize() throws IOException
    {
        BufferedImage image = ImageIO.read(getClass().getResourceAsStream("/com/killsto/icon.png"));
        assertNotNull(image);
        assertEquals(32, image.getWidth());
        assertEquals(32, image.getHeight());
        assertTrue(image.getColorModel().hasAlpha());
        assertTrue(hasTransparentPixel(image));
    }

    private static boolean hasTransparentPixel(BufferedImage image)
    {
        for (int y = 0; y < image.getHeight(); y++)
        {
            for (int x = 0; x < image.getWidth(); x++)
            {
                if ((image.getRGB(x, y) >>> 24) == 0)
                {
                    return true;
                }
            }
        }
        return false;
    }
}

