import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DisplayModelFactoryTest
{
    private final DisplayModelFactory factory = new DisplayModelFactory();
    private ActivityDefinition vorkath;

    @Before
    public void setUp()
    {
        vorkath = ActivityCatalog.load(new Gson()).findByKillCountName("Vorkath");
    }

    @Test
    public void doesNotAssumeEverythingMissingBeforeSync()
    {
        ActivityDisplayModel model = factory.create(
            vorkath, 100, Collections.emptySet(), SyncState.NOT_SYNCED, true);

        assertTrue(model.getMissing().isEmpty());
        assertEquals(SyncState.NOT_SYNCED, model.getSyncState());
    }

    @Test
    public void sortsRarestFirstAndIncludesEveryMissingItem()
    {
        ActivityDisplayModel model = factory.create(
            vorkath, 1000, Collections.emptySet(), SyncState.SYNCED, true);

        assertEquals(6, model.getMissing().size());
        assertEquals(5000D, model.getMissing().get(0).getDrop().normalizedRate(), 0D);
        assertTrue(model.getMissing().get(0).getCumulativeChance() > 0D);
    }

    @Test
    public void removesObtainedItemsAndCalculatesOverRate()
    {
        HashSet<Integer> obtained = new HashSet<>();
        obtained.add(11286);
        obtained.add(22006);
        ActivityDisplayModel model = factory.create(
            vorkath, 4000, obtained, SyncState.SYNCED, false);

        assertEquals("1000 over rate", model.getMissing().get(0).killsMetric());
        assertEquals("Vorki", model.getMissing().get(0).getDrop().getName());
        assertEquals(5, model.getDryTier());
        assertTrue(model.getDryMessage().startsWith("Dry 5 · "));
    }

    @Test
    public void commonMissingItemCanBeDryWhileRarestMissingItemIsUnderRate()
    {
        HashSet<Integer> obtained = new HashSet<>();
        obtained.add(11286);
        obtained.add(22006);
        obtained.add(22106);

        ActivityDisplayModel model = factory.create(
            vorkath, 1500, obtained, SyncState.SYNCED, false);

        assertTrue(model.getMissing().stream()
            .anyMatch(progress -> progress.getDrop().getName().equals("Vorki")));
        assertTrue(model.getMissing().stream()
            .anyMatch(progress -> progress.getDrop().getName().equals("Dragonbone necklace")));
        assertEquals(3, model.getDryTier());
        assertTrue(model.getDryMessage().startsWith("Dry 3 · "));
    }

    @Test
    public void capsDryJokesAtTierFive()
    {
        ActivityDisplayModel model = factory.create(
            vorkath, 1000000, Collections.emptySet(), SyncState.SYNCED, false);

        assertEquals(5, model.getDryTier());
        assertTrue(model.getDryMessage().startsWith("Dry 5 · "));
    }

    @Test
    public void doesNotUseCompletionCountAsRewardSearchCount()
    {
        ActivityDefinition guardians = ActivityCatalog.load(new Gson())
            .findByKillCountName("Guardians of the Rift");
        ActivityDisplayModel model = factory.create(
            guardians, 500, Collections.emptySet(), SyncState.SYNCED, true);

        assertEquals("Completions 500", model.getKillCountText());
        assertNull(model.getRateCount());
        assertTrue(model.getMissing().get(0).progressMetric(guardians.getRateUnit()).startsWith("? searches"));
        assertEquals(0, model.getDryTier());
    }

    @Test
    public void usesAuthoritativeRewardSearchesForGuardiansDryness()
    {
        ActivityDefinition guardians = ActivityCatalog.load(new Gson())
            .findByKillCountName("Guardians of the Rift");
        ActivityDisplayModel model = factory.create(
            guardians, 500, 4500, Collections.emptySet(), SyncState.SYNCED, true);

        assertEquals(Integer.valueOf(4500), model.getRateCount());
        assertEquals("Searches 4500", model.getRateCountText());
        assertEquals("500 searches over rate", model.getMissing().get(0)
            .progressMetric(guardians.getRateUnit()));
        assertTrue(model.getDryTier() > 0);
    }

    @Test
    public void doesNotInventPersonalProgressForVariableZalcanoRates()
    {
        ActivityDefinition zalcano = ActivityCatalog.load(new Gson())
            .findByKillCountName("Zalcano");
        ActivityDisplayModel model = factory.create(
            zalcano, 1975, Collections.emptySet(), SyncState.SYNCED, true);

        assertEquals(4, model.getMissing().size());
        assertEquals("personal rate varies", model.getMissing().stream()
            .filter(progress -> progress.getDrop().getName().equals("Zalcano shard"))
            .findFirst()
            .get()
            .progressMetric(zalcano.getRateUnit()));
        assertEquals(2, model.getDryTier());
        assertTrue(model.getDryMessage().startsWith("Dry 2 · "));
    }
}

package com.killsto.service;

import java.util.HashSet;
