import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class DryJokeLibraryTest
{
    @Test
    public void providesFiveJokesForTiersOneThroughFourAndTenForTierFive()
    {
        for (int tier = 1; tier <= 4; tier++)
        {
            assertEquals(5, collectJokes(tier).size());
        }
        assertEquals(10, collectJokes(5).size());
    }

    @Test
    public void includesTheSelectedRestartJoke()
    {
        assertTrue(collectJokes(2).contains(
            "Dry 2 · Have you tried turning your luck off and on again?"));
    }

    @Test
    public void cyclesThroughAllTierFiveJokesAtLaterDrynessSteps()
    {
        Set<String> jokes = new HashSet<>();
        for (long dryStep = 5; dryStep < 15; dryStep++)
        {
            jokes.add(DryJokeLibrary.forActivity("vorkath", 5, dryStep));
        }
        assertEquals(10, jokes.size());
    }

    private static Set<String> collectJokes(int tier)
    {
        Set<String> jokes = new HashSet<>();
        for (int index = 0; index < 1000; index++)
        {
            jokes.add(DryJokeLibrary.forActivity("activity-" + index, tier));
        }
        return jokes;
    }
}

