                Arrays.asList("Zalcano shard", "1/750-1/1,500", "personal rate varies", "chance varies"));
            row.setPreferredLocation(new Point(3, 5));
            row.setPreferredSize(new Dimension(213, 0));

            Dimension rendered = row.render(graphics);

            assertEquals(213, rendered.width);
            assertTrue(rendered.height >= graphics.getFontMetrics().getHeight() * 4);
            assertEquals(rendered, row.getBounds().getSize());
        }
        finally
        {
            graphics.dispose();
        }
    }
}

package com.killsto.ui;

import com.killsto.model.SyncState;
import com.killsto.model.OwnershipSource;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class KillsToPanelTest
{
    @Test
    public void reportsEverySyncStateHonestly()
    {
        assertEquals("Local Collection Log: not synced",
            KillsToPanel.syncStatusText(SyncState.NOT_SYNCED));
        assertEquals("Local Collection Log: stale",
            KillsToPanel.syncStatusText(SyncState.STALE));
        assertEquals("Local Collection Log: synced",
            KillsToPanel.syncStatusText(SyncState.SYNCED));
    }

    @Test
    public void identifiesRuneProfileOwnershipHonestly()
    {
        assertEquals("RuneProfile Collection Log: synced",
            KillsToPanel.syncStatusText(SyncState.SYNCED, OwnershipSource.RUNEPROFILE));
        assertEquals("RuneProfile Collection Log: stale",
            KillsToPanel.syncStatusText(SyncState.STALE, OwnershipSource.RUNEPROFILE));
    }
}
